package com.learnagent.websearch;
import com.fasterxml.jackson.annotation.JsonProperty;import java.net.URI;import java.time.*;import java.time.format.DateTimeFormatter;import java.util.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Component;import org.springframework.web.client.RestClient;
@Component public class TavilyWebSearchProvider implements WebSearchProvider{private final String apiKey;private final String endpoint;private final RestClient client;public TavilyWebSearchProvider(@Value("${learnagent.web-search.api-key:}")String apiKey,@Value("${learnagent.web-search.endpoint:https://api.tavily.com/search}")String endpoint,RestClient.Builder builder){this.apiKey=apiKey;this.endpoint=endpoint;this.client=builder.build();}@Override public boolean isConfigured(){return apiKey!=null&&!apiKey.isBlank();}@Override public String providerName(){return "Tavily";}@Override public List<WebSearchResult> search(String query,int limit){if(!isConfigured())throw new WebSearchUnavailableException("WEB_SEARCH_NOT_CONFIGURED: set TAVILY_API_KEY before using external search.");if(query==null||query.isBlank())throw new IllegalArgumentException("Search query is required.");int safeLimit=Math.max(1,Math.min(limit,10));try{TavilyResponse response=client.post().uri(endpoint).header("Authorization","Bearer "+apiKey).body(new TavilyRequest(query.trim(),"basic",safeLimit,"general",false,false,true)).retrieve().body(TavilyResponse.class);if(response==null||response.results()==null)return List.of();return response.results().stream().map(item->new WebSearchResult(item.title(),item.content(),item.url(),host(item.url()),parse(item.publishedDate()))).toList();}catch(Exception exception){throw new WebSearchUnavailableException("WEB_SEARCH_FAILED: "+root(exception),exception);}}private String host(String value){try{return URI.create(value).getHost();}catch(Exception ignored){return "Web";}}private Instant parse(String value){if(value==null||value.isBlank())return null;try{return ZonedDateTime.parse(value,DateTimeFormatter.RFC_1123_DATE_TIME).toInstant();}catch(Exception ignored){return null;}}private String root(Throwable error){Throwable current=error;while(current.getCause()!=null)current=current.getCause();return current.getMessage()==null?current.getClass().getSimpleName():current.getMessage();}private record TavilyRequest(String query,@JsonProperty("search_depth")String searchDepth,@JsonProperty("max_results")int maxResults,String topic,@JsonProperty("include_answer")boolean includeAnswer,@JsonProperty("include_raw_content")boolean includeRawContent,@JsonProperty("include_published_date")boolean includePublishedDate){}private record TavilyResponse(List<TavilyResult> results){}private record TavilyResult(String title,String url,String content,@JsonProperty("published_date")String publishedDate){}
}
